import{z as i,x as B,o as l,c as d,q as s,j as o,D as E,d as e,s as A,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"Meltdown 与 KPTI","description":"","frontmatter":{"title":"Meltdown 与 KPTI","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/meltdown-kpti.md","filePath":"cs/meltdown-kpti.md","lastUpdated":1791413859000}'),p={name:"cs/meltdown-kpti.md"};function c(T,a,P,m,h,D){const r=B("Mermaid");return l(),d("div",null,[a[2]||(a[2]=s('<h1 id="meltdown-与-kpti" tabindex="-1">Meltdown 与 KPTI <a class="header-anchor" href="#meltdown-与-kpti" aria-label="Permalink to &quot;Meltdown 与 KPTI&quot;">​</a></h1><div class="epigraph"><p>乱序允许 load 在权限检查完成前把内核映射的数据读进窗口；异常会冲刷寄存器，但缓存已经按那数据编过码。KPTI 让用户态页表里根本没有那一页。</p><footer>—— 据 Lipp et al., Meltdown, USENIX Security 2018 整理</footer></div><p><a href="/cs/spectre-variants">上一课</a> 的根是预测器。<a href="/cs/retire-precise-exception">退休与精确异常</a> 保证故障指令不提交。许多核为了快，把「页表里有映射」的内核地址留在用户 CR3 里，靠权限位在使用时 trap。本课不给攻击步骤。缺口是 <strong>Meltdown：故障路径上的瞬态 load，以及 KPTI 用两套页表堵住映射。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户 load 内核地址：权限失败应 trap。若微结构先把数据送进依赖的推测 load 再检查，瞬态值可以当 <a href="/cs/spectre-variants">Spectre</a> 那样的 cache 索引。缺口不是 BTB 训练，而是<strong>权限检查相对 load 执行太晚，且内核地址在用户页表里仍翻译得通。</strong></p><p><span class="marginnote">术语翻译：「瞬态执行」指最终被撤销的指令留下的物理副作用。指令作废、寄存器回滚，但它中途访问过的 cache 行已经被加载——量「哪行变快了」就能把那份数据侧信道读出，回滚管不到 cache。</span></p><p><span class="marginnote">KPTI（KAISER）：用户 CR3 不含内核映射（少量跳板除外），瞬态翻译失败，数据进不了窗口。代价是 syscall/中断多一次 CR3 切换与 TLB 压力，见 <a href="/cs/tlb-hierarchy-pwc">TLB 层次</a>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬件：先检查权限再写物理数据进流水，或故障 load 永不填用户可见 cache。软件：KPTI 分离页表。微码与新核的「幽灵缓解」改乱序许可。本课不讨论如何把瞬态值编进 cache 集。</p><p><span class="marginnote">为什么重要：Meltdown 与 Spectre 的堵法不同——Spectre 靠「别喂毒给预测器」（改写敏感代码的访问模式），Meltdown 靠「根本不给映射」（KPTI）。认错漏洞类型去上缓解，性能税白交，洞还在。</span></p>',10)),(l(),o(n,null,{default:E(()=>[A(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20LD%5B%22%E7%94%A8%E6%88%B7%20load%20%E5%86%85%E6%A0%B8%20VA%22%5D%20--%3E%20PERM%5B%22%E6%9D%83%E9%99%90%E6%A3%80%E6%9F%A5%22%5D%0A%20%20LD%20--%3E%20SPEC%5B%22%E6%A3%80%E6%9F%A5%E5%89%8D%E6%95%B0%E6%8D%AE%E5%B7%B2%E8%BF%9B%E7%AA%97%E5%8F%A3%22%5D%0A%20%20SPEC%20--%3E%20CACHE%5B%22cache%20%E5%89%AF%E4%BD%9C%E7%94%A8%22%5D%0A%20%20KPTI%5B%22%E7%94%A8%E6%88%B7%E9%A1%B5%E8%A1%A8%E6%97%A0%E5%86%85%E6%A0%B8%E9%A1%B5%22%5D%20--%3E%20FAIL%5B%22%E7%BF%BB%E8%AF%91%E5%A4%B1%E8%B4%A5%EF%BC%8C%E6%97%A0%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("与 Spectre 的差别：不必误训练条件分支；依赖的是乱序与延迟 trap。KPTI 增加 "),t("a",{href:"/cs/syscall-abi"},"syscall"),e(" 路径上的 TLB miss，是用翻译隔离换瞬态隔离。后续硅把 Meltdown 类关洞后，OS 可在部分 CPU 上关 KPTI 以收回性能。")],-1)),a[5]||(a[5]=t("p",null,"KPTI 的两套页表各装什么、切换发生在哪，可以单独画开：",-1)),(l(),o(n,null,{default:E(()=>[A(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20UPT%5B%22%E7%94%A8%E6%88%B7%E6%80%81%E9%A1%B5%E8%A1%A8%22%5D%20--%3E%20UMAP%5B%22%E4%BB%85%E7%94%A8%E6%88%B7%E6%98%A0%E5%B0%84%E5%8A%A0%E5%B0%91%E9%87%8F%E8%B7%B3%E6%9D%BF%22%5D%0A%20%20KPT%5B%22%E5%86%85%E6%A0%B8%E6%80%81%E9%A1%B5%E8%A1%A8%22%5D%20--%3E%20KMAP%5B%22%E7%94%A8%E6%88%B7%E6%98%A0%E5%B0%84%E5%8A%A0%E5%85%A8%E9%83%A8%E5%86%85%E6%A0%B8%E6%98%A0%E5%B0%84%22%5D%0A%20%20SYS%5B%22%E8%BF%9B%E5%85%A5%20syscall%22%5D%20--%3E%20SW1%5B%22%E5%88%87%20CR3%20%E5%88%B0%E5%86%85%E6%A0%B8%E9%A1%B5%E8%A1%A8%22%5D%0A%20%20SW1%20--%3E%20KPT%0A%20%20RET%5B%22%E8%BF%94%E5%9B%9E%E7%94%A8%E6%88%B7%E6%80%81%22%5D%20--%3E%20SW2%5B%22%E5%88%87%E5%9B%9E%E7%94%A8%E6%88%B7%E9%A1%B5%E8%A1%A8%22%5D%0A%20%20SW2%20--%3E%20UPT%0A%20%20SW1%20--%3E%20TAX%5B%22%E6%97%A0%20PCID%20%E6%97%B6%20TLB%20%E5%A4%A7%E9%87%8F%E5%A4%B1%E6%95%88%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p>PCID/ASID 让两套页表切换不必全冲 TLB，把 KPTI 税从「每次 syscall 冷 TLB」降到「换 ASID」。没有 PCID 的核上，KPTI 的 <a href="/cs/hugepage-tlb-reach">大页覆盖</a> 收益也更明显。</p><p><span class="marginnote">数字实例：没有 PCID 时，每次 syscall 进出各换一次 CR3，用户态 TLB 近乎清空，热路径上多出一串页表遍历；有 PCID 则给两套页表各发一个编号，切换互不冲账。同一条缓解措施，代价可以差出一个数量级。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有故障类瞬态变体点名。Rowhammer 下一课把「正确 cache 协议」换成 DRAM 行间漏电，不靠推测。Prime+Probe 是通用缓存侧信道，最后一课，Spectre/Meltdown 只是它的一种编码器。</p><p>后课默认：Meltdown 靠延迟权限 + 映射仍在；KPTI 拆映射。DRAM 扰动是另一物理层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Meltdown：故障前的瞬态 load 留下缓存足迹。</li><li>KPTI 用页表隔离，付 TLB 与 syscall 税。</li><li>DRAM 行干扰是下一课 Rowhammer。</li><li>出处：Lipp et al., <em>USENIX Security</em>, 2018。</li></ul>',7))])}const f=i(p,[["render",c]]);export{S as __pageData,f as default};
